import pickle
def SearchEmployee(EmpNo):
    found = False
    with open('emp.dat', 'rb') as f:
        try:
            while True:
                data = pickle.load(f)
                if EmpNo in data:
                    print('Name:', data[EmpNo])
                    found = True
        except EOFError:
            pass
    if not found:
        print('Employee not found')
```

