-- 1. Sort by Amount
SELECT * FROM Orders ORDER BY Amount DESC;

-- 2. Total Amount per SID
SELECT SID, SUM(Amount) FROM Orders GROUP BY SID;

-- 3. Filter using HAVING
SELECT SID, SUM(Amount) FROM Orders GROUP BY SID HAVING SUM(Amount) > 10000;

-- 4. JOIN tables
SELECT Salesman.SName, Orders.Amount 
FROM Salesman JOIN Orders ON Salesman.SID = Orders.SID;
